\draw[black,->] (0,0)--(4.5,0) node[right] {$t$ (days)};
\draw[black,->] (0,0)--(0,4.5) node[above] {$h$ (mm)};
\foreach \x in {1,...,4} {\draw[black] (\x,0)--(\x,-0.08);\path (\x,-0.12) node[below,font=\fontsize{8.5}{10}\selectfont] {$\x$};}
\foreach \y/\v in {1/6,2/12,3/18,4/24} {\draw[black] (0,\y)--(-0.08,\y);\path (-0.12,\y) node[left,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\path (0,0) node[below left,font=\fontsize{8.5}{10}\selectfont] {$0$};
\draw[mathblue,thick] (0,0)--(4,4);
\foreach \a in {0,...,4} {\fill[black] (\a,\a) circle (1.8pt);}
\end{tikzpicture}
[/tikz]
